contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount1, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(address(this).balance >= amount1 + amount2);
        require(amount1 == 10 wei);
        require(amount2 == 10 wei);
        c.play{value: amount1}(); if (__ESBMC_reverted()) return;
        uint prePot = c.pot(); if (__ESBMC_reverted()) return;
        uint preBalance = address(c).balance;
        c.play{value: amount2}(); if (__ESBMC_reverted()) return;
        uint postPot = c.pot(); if (__ESBMC_reverted()) return;
        uint postBalance = address(c).balance;
        assert(
            (postPot == 0 && postBalance == preBalance) ||
            (postPot == prePot + amount2 && postBalance == preBalance + amount2)
        );
    }
}

