pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount1 + amount2);
        amount1 = 10 wei;
        amount2 = 10 wei;
        try c.play{value: amount1}() {} catch { return; }
        uint256 prePot;
        try c.pot() returns (uint256 __r) { prePot = __r; } catch { return; }
        uint preBalance = address(c).balance;
        try c.play{value: amount2}() {} catch { return; }
        uint256 postPot;
        try c.pot() returns (uint256 __r) { postPot = __r; } catch { return; }
        uint postBalance = address(c).balance;
        assertTrue((postPot == 0 && postBalance == preBalance) ||
            (postPot == prePot + amount2 && postBalance == preBalance + amount2));
    }

    function testFuzz_run(uint256 amount1, uint256 amount2) public {
        _run(amount1, amount2);
    }

    receive() external payable {}
}
